 for(int mode=0;mode<4;++mode){auto c=context;auto o=options;if(mode==0)c.hold=false;if(mode==1)c.focused=false;if(mode==2)c.live=false;if(mode==3)o.armed=false;c.now+=.02;result=tracker.update(boxes,c,o);check(!result.engaged&&result.moveX==0&&result.moveY==0,"Output survived hold/focus/live/arm gate");}
