lse;check(!activation.update(input,binding).active,"START lock survived focus loss");activation.requestStart(50,binding);input.now=61;check(!activation.update(input,binding).active&&!activation.update(input,binding).pending,"Expired START request survived");activation.requestStart(70,binding);input.now=70;input.ready=false;check(!activation.update(input,binding).pending,"Source failure retained START request");input.ready=true;input.focused=true;activation.requestStart(80,binding);input.now=80;binding.armed=false;check(!activation.update(input,binding).active,"Disarm did not clear pending START");
